import products from './products.json' with { type: 'json' };

const TOOL_NAME = 'inventory_search';

const toolDefinition = {
  name: TOOL_NAME,
  description: 'Search products by name (case-insensitive substring match).',
  inputSchema: {
    type: 'object',
    properties: {
      query: {
        type: 'string',
        description: 'Substring to search for in product names (case-insensitive).',
      },
      limit: {
        type: 'integer',
        minimum: 1,
        maximum: 10,
        description: 'Maximum number of results to return (1-10).',
      },
    },
    required: ['query'],
    additionalProperties: false,
  },
};

export async function listTools() {
  return [toolDefinition];
}

export async function callTool(name, args = {}) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }

  const { query, limit } = args || {};

  if (typeof query !== 'string' || query.length === 0) {
    throw new Error('Invalid arguments: "query" must be a non-empty string');
  }

  let effectiveLimit = limit === undefined ? 10 : limit;
  if (!Number.isInteger(effectiveLimit) || effectiveLimit < 1 || effectiveLimit > 10) {
    throw new Error('Invalid arguments: "limit" must be an integer between 1 and 10');
  }

  const needle = query.toLowerCase();
  const matches = products.filter((p) => p.name.toLowerCase().includes(needle));
  const sliced = matches.slice(0, effectiveLimit);

  const lines = sliced.map((p) => `${p.id}: ${p.name}`);
  const text = sliced.length
    ? `Found ${sliced.length} product(s):\n` + lines.join('\n')
    : 'No products found.';

  return {
    content: [{ type: 'text', text }],
  };
}

